import { renderMessage, type Message } from '@llenamos/core'
export async function sendMessage(message: Message, key: string) {
 const rendered = renderMessage(message)
 const email = message.channel === 'email'
 const configured = email ? process.env.RESEND_API_KEY && process.env.EMAIL_FROM : process.env.WHATSAPP_TOKEN && process.env.WHATSAPP_PHONE_NUMBER_ID
 if (!configured) return { status: process.env.FUNCTIONS_EMULATOR === 'true' ? 'captured' : 'not_configured', rendered: { subject: rendered.subject, body: rendered.body }, provider: null, providerMessageId: null } as const
 const buttons = rendered.buttons.map(b => ({ type: 'reply', reply: { id: `${key}:${b.id}`, title: b.title } }))
 const payload = email ? { from: process.env.EMAIL_FROM, to: [message.to], subject: rendered.subject, text: rendered.body } : { messaging_product: 'whatsapp', to: message.to.slice(1), ...(buttons.length ? { type: 'interactive', interactive: { type: 'button', body: { text: rendered.body }, action: { buttons } } } : { type: 'text', text: { body: rendered.body } }) }
 const response = await fetch(email ? 'https://api.resend.com/emails' : `https://graph.facebook.com/v23.0/${process.env.WHATSAPP_PHONE_NUMBER_ID}/messages`, { method: 'POST', headers: { Authorization: `Bearer ${email ? process.env.RESEND_API_KEY : process.env.WHATSAPP_TOKEN}`, 'Content-Type': 'application/json', ...(email ? { 'Idempotency-Key': key } : {}) }, body: JSON.stringify(payload), signal: AbortSignal.timeout(15000) })
 if (!response.ok) throw new Error(`El proveedor ha rechazado el envío (${response.status}).`)
 const result = await response.json() as { id?: string; messages?: { id: string }[] }
 const providerMessageId = email ? result.id : result.messages?.[0]?.id
 if (!providerMessageId) throw new Error('El proveedor no ha devuelto un identificador de envío.')
 return { status: 'sent', rendered: { subject: rendered.subject, body: rendered.body }, provider: email ? 'resend' : 'whatsapp_cloud', providerMessageId } as const
}
